-- 1122: Blog post — "MB-910 Dynamics 365 Fundamentals (CRM) in Singapore: Course, Funding and What Replaced the Exam"
--
--       Lead-in post for WSQ - Microsoft Dynamics 365 Fundamentals (CRM) (MB-910) (TGS-2023040481).
--       Backdated to 2025-09-12 (published, status 1). No LinkedIn / Facebook share is
--       performed: linkedin_urn carries the manual-skip sentinel and the post ships
--       already-published, so publishDue never picks it up.
--
-- Every figure below was read off the LIVE course page on 2026-08-26, not invented:
--   * Fee card: full $1,000.00, GST $90.00 (9%), baseline nett $590.00
--     (SG/PR 21+, 50%), MCES/SME nett $390.00 (SG 40+, 70%).
--   * Course information: 2 days / 16 hrs, Beginner, 2 hrs assessment.
--   * Funding validity 4 Dec 2023 - 3 Dec 2027; Absentee Payroll $4.50/hr.
--   * Skills Framework: Customer Relationship Management (RET-RAN-4001-1.1).
--   * Exam weightings from the official study guide, skills measured as of 17 Dec 2024.
--   * NOTE: the MB-910 exam RETIRED on 31 December 2025. The post says so plainly in a
--     notice near the top, in the FAQ, and in the meta description, and it does NOT tell
--     readers to book the exam. The WSQ course itself still runs and is still funded.
--   * No exam-specific practice-exam URL exists, so the post links only the portal root
--     (never a deep link that 404s).
--
-- Notes for future editors:
--  * apply.php splits statements on ";" at end-of-line — the content HTML below is ONE line.
--  * Idempotent: WHERE NOT EXISTS on url_key, INSERT IGNORE on tag links. Safe to re-run.
--  * SG-only guard via @mms_instance — the CTA course is SG WSQ, absent on MY/GH.
--  * hero_image_url is NOT set here (SQL cannot render one) — generate on prod post-deploy.

SET @is_sg := IF(@mms_instance = 'SG', 1, 0);

INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `source_sku`, `meta_title`, `meta_description`, `meta_keywords`, `linkedin_urn`, `created_at`, `updated_at`) SELECT 'MB-910 Dynamics 365 Fundamentals (CRM) in Singapore: Course, Funding and What Replaced the Exam', 'mb-910-dynamics-365-fundamentals-crm-singapore-guide', 'The MB-910 exam retired on 31 December 2025, but the WSQ course still runs and is still funded &mdash; $590 nett, or $390 for Singapore Citizens aged 40 and above. Here is what the course covers and what the current alternatives are.', '<div class="mmd-summary"><div class="mmd-summary-label">Summary</div><p><strong>MB-910</strong> is the Microsoft credential for sales, service and operations staff working on a Dynamics 365 rollout. This guide covers what the exam measures, what the 2 days WSQ course covers, and what you pay after SkillsFuture funding &mdash; <strong>$590</strong> for Singapore Citizens and PRs aged 21 and above, or <strong>$390</strong> for Singapore Citizens aged 40 and above.</p></div><p><strong>Please note:</strong> the <strong>MB-910</strong> certification exam was retired by Microsoft on <strong>31 December 2025</strong>. Microsoft has not named a direct successor exam. The WSQ course below still runs, is still funded, and still leads to a WSQ Statement of Attainment &mdash; the skills it teaches are unchanged. What has changed is that this particular Microsoft exam can no longer be booked. <a href="https://www.tertiarycourses.com.sg/microsoft-certifications-exams.html">See the current Microsoft certification courses</a>.</p><h2>Why MB-910 is worth taking</h2><p>Dynamics 365 rollouts succeed or fail on whether the people using them understand the model behind the screens &mdash; how leads become opportunities, how cases route, how field service scheduling actually works. This course covers the customer-engagement side of Dynamics 365 end to end.</p><ul><li><strong>Covers all four customer-engagement apps</strong> &mdash; Sales, Customer Service, Field Service and Customer Insights &mdash; rather than just one.</li><li><strong>Built for business users</strong>, not developers or administrators.</li><li><strong>Useful during a rollout</strong>, when the gap between what the system can do and what the team knows is widest.</li><li><strong>Leads to CRM and Dynamics operational roles</strong>, which are consistently in demand in Singapore enterprises.</li></ul><p>The course is mapped to the Skills Framework under <strong>Customer Relationship Management</strong> (TSC code RET-RAN-4001-1.1), and leads to roles such as Dynamics 365 Administrator, CRM Analyst, Customer Service Manager, Sales Operations Analyst. <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-dynamics-365-fundamentals-crm-mb-910.html">Check the funding you qualify for</a>.</p><h2>The MB-910 exam at a glance</h2><table><tbody><tr><td>Exam</td><td>MB-910: Microsoft Dynamics 365 Fundamentals (CRM)</td></tr><tr><td>Status</td><td><strong>Retired on 31 December 2025</strong></td></tr><tr><td>Replaced by</td><td>No direct successor named by Microsoft</td></tr><tr><td>Passing score</td><td>700 out of 1000 (scaled)</td></tr></tbody></table><h2>MB-910 exam domains and weightings</h2><p>These are the skills measured on the official study guide. The weightings tell you where to spend your revision time.</p><table><thead><tr><th>Skills measured</th><th>Weighting</th></tr></thead><tbody><tr><td>Describe Dynamics 365 Customer Insights</td><td>15&ndash;20%</td></tr><tr><td>Describe Dynamics 365 Sales</td><td>20&ndash;25%</td></tr><tr><td>Describe Dynamics 365 Customer Service</td><td>20&ndash;25%</td></tr><tr><td>Describe Dynamics 365 Field Service</td><td>15&ndash;20%</td></tr><tr><td>Describe the core capabilities of Dynamics 365 customer engagement apps</td><td>15&ndash;20%</td></tr></tbody></table><p><em>Source: official Microsoft study guide, skills measured as of 17 Dec 2024.</em></p><h2>What the WSQ course covers</h2><p>The 2 days (16 hrs) <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-dynamics-365-fundamentals-crm-mb-910.html"><strong>WSQ - Microsoft Dynamics 365 Fundamentals (CRM) (MB-910)</strong></a> course is pitched at <strong>Beginner</strong> level and is delivered in our Woodlands classroom with hands-on labs, followed by a 2 hrs assessment. The outline tracks the official objectives:</p><ol><li>Foundations of Dynamics 365 customer engagement apps</li><li>Shared activities and integration options in Dynamics 365 customer engagement apps</li><li>Explore Dynamics 365 Customer Insights – Journeys</li><li>Describe Dynamics 365 Customer Insights - Data and Dynamics 365 Customer Voice</li><li>Explore Dynamics 365 Sales</li><li>Describe Dynamics 365 Sales capabilities and related apps</li><li>Explore Dynamics 365 Customer Service</li><li>Describe Dynamics 365 Customer Service capabilities and related apps</li><li>Explore Dynamics 365 Field Service</li><li>Describe Dynamics 365 Field Service scheduling capabilities and related apps</li></ol><h2>Practise what you learn</h2><p>Course participants get access to our <a href="https://exams.tertiaryinfotech.com/practice-exams">Practice Exam Portal</a>, which carries timed mock papers across the Microsoft certification track. Rehearsing under exam conditions is the single best predictor of a first-time pass.</p><h2>What you actually pay: funding for MB-910 training</h2><p>The full fee is $1,000 before GST. As an SWDA-funded WSQ course, the subsidy depends on your citizenship, age and who is sponsoring you:</p><table><thead><tr><th>Who you are</th><th>Subsidy</th><th>You pay (incl. GST)</th></tr></thead><tbody><tr><td>Non-funded / international participants</td><td>&ndash;</td><td>$1,090</td></tr><tr><td>Singapore Citizen or PR, aged 21 and above</td><td>50%</td><td><strong>$590</strong></td></tr><tr><td>Singapore Citizen aged 40 and above (MCES), or SME-sponsored</td><td>70%</td><td><strong>$390</strong></td></tr></tbody></table><p><em>GST of $90 is charged at 9% on the full course fee of $1,000, as required for SWDA-funded courses &mdash; the subsidy applies to the course fee, not the tax.</em></p><p>Funding for this course is valid from <strong>4 Dec 2023</strong> to <strong>3 Dec 2027</strong>. You must register and complete the course within that window to qualify.</p><div class="mmd-faq"><details class="mmd-faq-item"><summary class="mmd-faq-q">1. SkillsFuture Credit (SFC)</summary><div class="mmd-faq-a"><p>Singaporeans aged 25 and above have an opening SkillsFuture Credit of $500 plus any top-ups, and those aged 40 and above received a $4,000 Mid-Career top-up. Credit can offset the fee payable after subsidy, though the Mid-Career top-up cannot be used on this course. <a href="https://www.tertiarycourses.com.sg/how-to-claim-skillsfuture-credit.html">How to claim SkillsFuture Credit</a>.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">2. SkillsFuture Enterprise Credit (SFEC)</summary><div class="mmd-faq-a"><p>Eligible employers can draw on SFEC to cover out-of-pocket costs when sponsoring staff. See our <a href="https://www.tertiarycourses.com.sg/sfec.html">SFEC guide</a> for who qualifies and how to claim.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">3. PSEA</summary><div class="mmd-faq-a"><p>Singapore Citizens can use Post-Secondary Education Account funds to offset the fee payable after subsidy. This course carries the PSEA tag, so it is eligible.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">4. UTAP</summary><div class="mmd-faq-a"><p>NTUC members can claim 50% of the unfunded fee under UTAP, capped at $250 a year, or $500 a year for members aged 40 and above. See the <a href="https://www.tertiarycourses.com.sg/utap.html">UTAP guide</a>.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">5. Absentee Payroll</summary><div class="mmd-faq-a"><p>Employers sponsoring staff can claim Absentee Payroll at $4.50 an hour, capped at $100,000 per enterprise per year, for the hours staff spend in training.</p></div></details></div><p><a href="https://www.tertiarycourses.com.sg/wsq-microsoft-dynamics-365-fundamentals-crm-mb-910.html"><strong>See the live fee breakdown for your profile &rarr;</strong></a></p><h2>How to get started</h2><ol><li><strong>Register for the 2 days WSQ course.</strong> Pick an intake on the <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-dynamics-365-fundamentals-crm-mb-910.html">course page</a> and apply your funding at checkout.</li><li><strong>Attend and complete the assessment.</strong> You need at least 75% attendance and a pass in the 2 hrs assessment to receive your WSQ Statement of Attainment.</li><li><strong>Rehearse on the practice exams</strong> until you are consistently clearing the pass mark under timed conditions.</li></ol><h2>Where to go after MB-910</h2><p>For deeper, role-specific Dynamics knowledge, Microsoft offers app-specific certifications in Sales and Customer Service. If your interest is the wider Microsoft business-applications stack, <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-power-platform-fundamentals-pl-900.html">PL-900</a> covers the Power Platform that Dynamics 365 is built on. Browse the full <a href="https://www.tertiarycourses.com.sg/microsoft-certifications-exams.html">Microsoft certification course catalogue</a> to plan the next rung.</p><h2>Frequently asked questions</h2><div class="mmd-faq"><details class="mmd-faq-item"><summary class="mmd-faq-q">Is the MB-910 exam still available?</summary><div class="mmd-faq-a"><p>No. Microsoft retired the MB-910 exam on 31 December 2025 and has not named a direct successor. The course still runs and still leads to a WSQ Statement of Attainment &mdash; the Dynamics 365 skills it teaches are unaffected.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">Is the course still worth taking if the exam has retired?</summary><div class="mmd-faq-a"><p>Yes, if your goal is the skills. The course covers Sales, Customer Service, Field Service and Customer Insights, and remains WSQ-funded with a nationally recognised Statement of Attainment. If your goal is specifically a Microsoft exam badge, look at the current Microsoft certification courses instead.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">Do I need technical experience?</summary><div class="mmd-faq-a"><p>No. This is a fundamentals-level course for business users.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">What funding is available?</summary><div class="mmd-faq-a"><p>Singapore Citizens and PRs aged 21 and above get 50% subsidy, rising to 70% for Citizens aged 40 and above. SkillsFuture Credit, PSEA and UTAP can offset the balance.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">How long is the course?</summary><div class="mmd-faq-a"><p>2 days (16 hours), followed by a 2-hour assessment.</p></div></details></div><h2>Register for Dynamics 365 Fundamentals (CRM) training</h2><p>Seats are limited and classes fill ahead of each intake. View upcoming dates and reserve your place on the <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-dynamics-365-fundamentals-crm-mb-910.html"><strong>WSQ - Microsoft Dynamics 365 Fundamentals (CRM) (MB-910)</strong></a> course page, or call us on +65 6100 0613 if you would like your funding worked out first.</p>', 'Tertiary Infotech Academy', 1, '2025-09-12', 'TGS-2023040481', 'TGS-2023040481', 'MB-910 Course Singapore | Dynamics 365 Fundamentals (CRM) | WSQ Funding', 'MB-910 Dynamics 365 Fundamentals (CRM) in Singapore. The MB-910 exam retired on 31 December 2025; the WSQ course still runs from $390 nett after funding. Full details and current alternatives.', 'mb-910 course singapore, dynamics 365 fundamentals (crm) certification, mb-910 exam, wsq microsoft course, skillsfuture microsoft certification, microsoft certification singapore, mb-910 funding, mb-910 training singapore', 'manual-skip-no-share', '2025-09-12 09:00:00', '2025-09-12 09:00:00' FROM DUAL WHERE @is_sg > 0 AND NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'mb-910-dynamics-365-fundamentals-crm-singapore-guide');

-- Tags (core Magento tag vocabulary; status 1 = approved)
INSERT INTO `tag` (`name`, `status`) SELECT 'Microsoft', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'Microsoft') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'Dynamics 365', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'Dynamics 365') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'MB-910', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'MB-910') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'CRM', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'CRM') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'WSQ', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'WSQ') x);

SET @post_id := (SELECT `post_id` FROM `mmd_blog_post` WHERE `url_key` = 'mb-910-dynamics-365-fundamentals-crm-singapore-guide');

INSERT IGNORE INTO `mmd_blog_post_tag` (`post_id`, `tag_id`) SELECT @post_id, `tag_id` FROM `tag` WHERE @post_id IS NOT NULL AND `name` IN ('Microsoft', 'Dynamics 365', 'MB-910', 'CRM', 'WSQ');

-- Seed the like count so the post does not ship showing "0 Likes" (same `likes < 100` guard
-- as migrations 868/869/1109/1117 — only raises into the band, never overwrites a real count).
UPDATE `mmd_blog_post` SET `likes` = 109 WHERE `url_key` = 'mb-910-dynamics-365-fundamentals-crm-singapore-guide' AND `likes` < 100;
